import{_ as e,c as o,o as t,a4 as n}from"./chunks/framework.BYxathSa.js";const m=JSON.parse('{"title":"Q15：事件循环（Event Loop）机制详解","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q15.md","filePath":"frontend/q15.md","lastUpdated":null}'),r={name:"frontend/q15.md"},s=n('<h1 id="q15-事件循环-event-loop-机制详解" tabindex="-1">Q15：事件循环（Event Loop）机制详解 <a class="header-anchor" href="#q15-事件循环-event-loop-机制详解" aria-label="Permalink to &quot;Q15：事件循环（Event Loop）机制详解&quot;">​</a></h1><p>JavaScript 是单线程的，需要事件循环来处理异步操作。</p><ul><li><strong>执行栈</strong>：同步代码在主线程上执行，形成一个执行栈。</li><li><strong>任务队列</strong>：异步任务完成后，回调函数进入队列等待执行。分为： <ul><li><strong>宏任务队列</strong>：script 整体、<code>setTimeout</code>、<code>setInterval</code>、I/O、UI 渲染、<code>postMessage</code> 等。</li><li><strong>微任务队列</strong>：<code>Promise.then/catch/finally</code>、<code>MutationObserver</code>、<code>queueMicrotask</code>。</li></ul></li></ul><p><strong>事件循环流程</strong>：</p><ol><li>执行一个宏任务（初始是 script 主代码）。</li><li>执行过程中产生的微任务进入微任务队列。</li><li>当前宏任务执行完毕后，<strong>清空微任务队列</strong>中的所有任务。</li><li>浏览器判断是否需要渲染更新（通常一帧一次）。</li><li>从宏任务队列中取出下一个宏任务，重复上述过程。</li></ol><p><strong>常见考点</strong>：为什么 <code>Promise</code> 的回调比 <code>setTimeout</code> 早？因为 <code>Promise.then</code> 是微任务，在下一个宏任务之前就清空了。</p>',6),i=[s];function c(l,a,d,p,_,u){return t(),o("div",null,i)}const h=e(r,[["render",c]]);export{m as __pageData,h as default};
